<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { DocumentoCajaChica, DocumentoCajaChicaPayload } from '../interfaces/documento-caja-chica.interface'
import { cambiarEstadoDocumentoCajaChica, guardarDocumentoCajaChica, listarDocumentosCajaChica, obtenerDocumentoCajaChica } from '../services/documento-caja-chica'
const rows = ref<DocumentoCajaChica[]>([]), search = ref(''), taxType = ref(''), loading = ref(false), error = ref(''), success = ref(''), showForm = ref(false), editing = ref<number | null>(null)
const blank = (): DocumentoCajaChicaPayload => ({ codigo: '', detalle: '', abreviatura: '', porcentaje_impuesto: 0, signo: 1, tipo_impuesto_retencion: 'I' })
const form = reactive(blank())
const filtered = computed(() => { const q = search.value.toLocaleUpperCase(); return rows.value.filter(x => (!q || `${x.codigo} ${x.detalle} ${x.abreviatura || ''}`.toLocaleUpperCase().includes(q)) && (!taxType.value || x.tipo_impuesto_retencion === taxType.value)) })
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { rows.value = await listarDocumentosCajaChica() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function create() { editing.value = null; Object.assign(form, blank()); showForm.value = true }
async function edit(item: DocumentoCajaChica) { loading.value = true; try { const x = await obtenerDocumentoCajaChica(item.id); editing.value = x.id; Object.assign(form, { codigo: x.codigo, detalle: x.detalle, abreviatura: x.abreviatura || '', porcentaje_impuesto: Number(x.porcentaje_impuesto), signo: x.signo, tipo_impuesto_retencion: x.tipo_impuesto_retencion }); showForm.value = true } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function save() { loading.value = true; error.value = ''; try { await guardarDocumentoCajaChica(editing.value, { ...form }); success.value = `Documento de caja chica ${editing.value ? 'actualizado' : 'registrado'} correctamente.`; showForm.value = false; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
async function toggle(item: DocumentoCajaChica) { const action = item.activo ? 'inactivar' : 'activar'; if (!confirm(`¿Desea ${action} ${item.detalle}?`)) return; loading.value = true; try { await cambiarEstadoDocumentoCajaChica(item.id); success.value = `Documento ${item.activo ? 'inactivado' : 'activado'} correctamente.`; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Documentos de caja chica</nav><header class="hero"><div class="mark">DC</div><div><small>MIA · FINANZAS · CAJA CHICA</small><h1>Documentos de caja chica</h1><p>Comprobantes e impuestos utilizados en la rendición de gastos menores.</p></div><strong>{{filtered.length}} registros</strong><button @click="create">+ Nuevo documento</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="filters"><input v-model.trim="search" placeholder="Buscar por código, detalle o abreviatura"><select v-model="taxType"><option value="">Todos los tipos</option><option value="I">Impuesto</option><option value="R">Retención</option></select><button class="soft" @click="search='';taxType=''">Limpiar</button></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!filtered.length" class="empty">No se encontraron documentos de caja chica.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Documento</th><th>Abreviatura</th><th>Impuesto</th><th>Signo</th><th>Clasificación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.detalle}}</td><td>{{item.abreviatura||'-'}}</td><td>{{Number(item.porcentaje_impuesto).toFixed(2)}}%</td><td><span :class="item.signo===1?'positive':'negative'">{{item.signo===1?'+1':'-1'}}</span></td><td>{{item.tipo_impuesto_retencion==='I'?'IMPUESTO':'RETENCIÓN'}}</td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} documento de caja chica</h2></div><button type="button" @click="showForm=false">×</button></header><div class="twocol"><label>Código<input v-model.trim="form.codigo" maxlength="10" required></label><label>Abreviatura<input v-model.trim="form.abreviatura" maxlength="30"></label></div><label>Detalle<input v-model.trim="form.detalle" maxlength="150" required></label><div class="threecol"><label>Porcentaje de impuesto<input v-model.number="form.porcentaje_impuesto" type="number" min="0" max="100" step="0.01" required></label><label>Signo<select v-model.number="form.signo"><option :value="1">Positivo (+1)</option><option :value="-1">Negativo (-1)</option></select></label><label>Clasificación<select v-model="form.tipo_impuesto_retencion"><option value="I">Impuesto</option><option value="R">Retención</option></select></label></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.51rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse;font-size:.5rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}.good,.bad,.positive,.negative{padding:4px 8px;border-radius:10px;font-size:.43rem;font-weight:800}.good,.positive{color:#267153;background:#e5f7ec}.bad,.negative{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:50px;text-align:center}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.twocol,.threecol{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.threecol{grid-template-columns:repeat(3,1fr)}.dialog footer{display:flex;justify-content:center;gap:8px;margin-top:15px}@media(max-width:650px){.filters,.twocol,.threecol{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
</style>
